{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { scan, ScanError } from './scanner.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

let tokens
try {
  tokens = scan(readFileSync(0).toString('utf8'))
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}

let out = ''
if (args[0] === 'tokens') {
  for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
} else {
  const counts = { ident: 0, keyword: 0, number: 0, punct: 0, rawstring: 0, string: 0 }
  for (const t of tokens) counts[t.kind]++
  for (const k of Object.keys(counts)) out += `${k} ${counts[k]}\n`
  out += `total ${tokens.length}\n`
}
process.stdout.write(out)
"}

